func storeAssertGetZeroOnError(
	tb testing.TB,
	s Store,
	fx StoreFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := s.Get(ctx, fx.Key())
	if err == nil {
		tb.Skip("Get answered for a cancelled context, so this check has no error to inspect")
	}

	var zero roledtypes.Payload
	if got != zero {
		tb.Errorf("Get must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

